function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // Draw bird
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/2 + Math.sin(t) * 50, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + Math.sin(t) * 50, H/2 + 20);
  ctx.lineTo(W/2 + Math.sin(t) * 50, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + Math.sin(t) * 50, H/2 + 20);
  ctx.lineTo(W/2 + Math.sin(t) * 50 - 20, H/2 + 40);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + Math.sin(t) * 50, H/2 + 20);
  ctx.lineTo(W/2 + Math.sin(t) * 50 + 20, H/2 + 40);
  ctx.stroke();

  // Draw fish
  ctx.beginPath();
  ctx.arc(W/2 + Math.cos(t) * 100, H/2 + 100, 30, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + Math.cos(t) * 100, H/2 + 130);
  ctx.lineTo(W/2 + Math.cos(t) * 100, H/2 + 160);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + Math.cos(t) * 100, H/2 + 130);
  ctx.lineTo(W/2 + Math.cos(t) * 100 - 30, H/2 + 150);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + Math.cos(t) * 100, H/2 + 130);
  ctx.lineTo(W/2 + Math.cos(t) * 100 + 30, H/2 + 150);
  ctx.stroke();

  // Draw rabbit
  ctx.beginPath();
  ctx.arc(W/2 + Math.sin(t + Math.PI/2) * 50, H/2 - 100, 25, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + Math.sin(t + Math.PI/2) * 50, H/2 - 75);
  ctx.lineTo(W/2 + Math.sin(t + Math.PI/2) * 50, H/2 - 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + Math.sin(t + Math.PI/2) * 50, H/2 - 75);
  ctx.lineTo(W/2 + Math.sin(t + Math.PI/2) * 50 - 25, H/2 - 65);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + Math.sin(t + Math.PI/2) * 50, H/2 - 75);
  ctx.lineTo(W/2 + Math.sin(t + Math.PI/2) * 50 + 25, H/2 - 65);
  ctx.stroke();

  ctx.restore();
}
